     3→import com.cowave.search.domain.index.dto.ChangedData
     4→import com.cowave.search.domain.index.dto.ChangedProductDocument
     5→import com.cowave.search.domain.index.enums.Operation
     6→import com.cowave.shared.utils.logger
     7→
     8→object ProductMergeStrategy : MergeStrategy<ChangedProductDocument> {
     9→    private val logger by logger()
    10→
    11→    override fun merge(documents: List<ChangedData<ChangedProductDocument>>): List<ChangedData<ChangedProductDocument>> {
    12→        return documents
    13→            .groupBy { it.id } // 같은 문서로 그룹핑
    14→            .map { (_, group) ->
    15→                if (group.size == 1) {
    16→                    group.first()
    17→                } else {
    18→                    var isChangedCategory = false
    19→                    var isChangedBrand = false
    20→                    var isChangedManufacturer = false
    21→
    22→                    group.sortedBy { it.offset } // offset 기준으로 정렬
    23→                        .fold(null as ChangedData<ChangedProductDocument>?) { acc, current ->
    24→                            when (current.op) {
    25→                                Operation.CREATE -> {
    26→                                    isChangedCategory = true
    27→                                    // Note. product의 brand, manufacturer 연동은 아직 되고 있지 않지만 미리 작업해둠
    28→                                    isChangedBrand = true
    29→                                    isChangedManufacturer = true
    30→                                }
    31→                                Operation.UPDATE -> {
    32→                                    // Note. update 메시지의 before가 null인 경우 존재
    33→                                    if (current.beforeData != null && current.afterData != null) {
    34→                                        if (current.beforeData.categoryId != current.afterData.categoryId) isChangedCategory = true
    35→                                        if (current.beforeData.brandId != current.afterData.brandId) isChangedBrand = true
    36→                                        if (current.beforeData.manufacturerId != current.afterData.manufacturerId) isChangedManufacturer = true
    37→                                    }
    38→                                }
    39→                                Operation.DELETE -> {
    40→                                    isChangedCategory = false
    41→                                    isChangedBrand = false
    42→                                    isChangedManufacturer = false
    43→                                }
    44→                            }
    45→
    46→                            merge(acc, current)
    47→                                .also {
    48→                                    if (it == null) {
    49→                                        // Note. merge result가 null인 경우, acc는 not null이 보장됨
    50→                                        logger.warn { "[ProductMergeStrategy] Unexpected operation. "  + diffLog(acc!!, current) }
    51→                                    }
    52→                                }
    53→                        }
    54→                        .apply {
    55→                            this?.shouldFetchCategory = isChangedCategory
    56→                            this?.shouldFetchBrand = isChangedBrand
    57→                            this?.shouldFetchManufacturer = isChangedManufacturer
    58→                        }
    59→                }
    60→            }
    61→            .filterNotNull()
    62→    }
    63→}

